import java.io.*;
import java.net.*;
import java.net.http.*;
import java.nio.file.*;
import java.util.*;

/** Deployment-level HTTP contracts without a handset or real Supabase credentials. */
public final class Protocol630Check {
    static final HttpClient HTTP=HttpClient.newHttpClient();static String base;
    interface Writer {void write(DataOutputStream out)throws Exception;}
    static void ok(boolean v,String s){if(!v)throw new AssertionError(s);System.out.println("PASS: "+s);}
    static DataInputStream call(String token,String action,Writer body)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(bytes);out.writeInt(GunnyServer.MAGIC);out.writeUTF(action);if(body!=null)body.write(out);HttpRequest.Builder req=HttpRequest.newBuilder(URI.create(base+"/api")).header("X-Gunny-Client","3");if(token!=null)req.header("Authorization","Bearer "+token);HttpResponse<byte[]> response=HTTP.send(req.POST(HttpRequest.BodyPublishers.ofByteArray(bytes.toByteArray())).build(),HttpResponse.BodyHandlers.ofByteArray());DataInputStream in=new DataInputStream(new ByteArrayInputStream(response.body()));int code=in.readUnsignedByte();if(code!=0)throw new IOException(in.readUTF());return in;}
    static String login(int i)throws Exception{return call(null,"login",out->{out.writeUTF("p"+i+"@protocol.test");out.writeUTF("test-password-123");}).readUTF();}
    static void reject(String token,String action,Writer body,String message)throws Exception{boolean bad=false;try{call(token,action,body);}catch(IOException expected){bad=true;}ok(bad,message);}
    static DataInputStream sync(String token,int turn,boolean seen,int sequence,int kind,int arg)throws Exception{return call(token,"sync",out->{out.writeInt(0);out.writeByte(0);out.writeBoolean(true);out.writeInt(turn);out.writeBoolean(seen);out.writeByte(kind==0?0:1);if(kind!=0){out.writeInt(sequence);out.writeByte(kind);out.writeShort(arg);}});}
    public static void main(String[] args)throws Exception{
        CloudStore.Memory store=new CloudStore.Memory();for(int i=0;i<6;i++)store.register("p"+i+"@protocol.test","test-password-123","Người "+i);
        try(GunnyServer server=new GunnyServer(new InetSocketAddress("127.0.0.1",0),Path.of("backend/assets"),store)){
            base="http://127.0.0.1:"+server.port();String[] tokens=new String[6];for(int i=0;i<6;i++)tokens[i]=login(i);String a=tokens[0],b=tokens[1];
            int id=call(a,"quick",o->o.writeByte(2)).readInt();GunnyServer.Room room=server.rooms.get(id);ok(room.count==6&&room.kind==2,"3v3 protocol creates six seats");for(int i=1;i<6;i++){int team=i%2;call(tokens[i],"join",o->{o.writeInt(id);o.writeByte(team);o.writeUTF("");});}for(int i=1;i<6;i++)call(tokens[i],"ready",o->o.writeBoolean(true));synchronized(room){room.start();room.phase=1;Arrays.fill(room.ground.solid,false);Arrays.fill(room.ground.solid,170*480,220*480,true);for(int i=0;i<6;i++)room.battle.units[i].y=170;room.battle.units[0].x=210;}
            int turn=room.battle.turn,x=room.battle.units[0].x;sync(a,turn,false,1,6,16*12+2);int moved=room.battle.units[0].x;ok(moved>x,"Bounded input frames apply movement on authoritative physics");sync(a,turn,false,1,6,16*12+2);ok(room.battle.units[0].x==moved,"Retrying acknowledged input never moves twice");sync(b,turn,false,1,6,16*12+2);ok(room.battle.units[0].x==moved,"Other player cannot drive the active actor");reject(a,"sync",o->{o.writeInt(0);o.writeByte(0);o.writeBoolean(true);o.writeInt(turn);o.writeBoolean(false);o.writeByte(1);o.writeInt(2);o.writeByte(6);o.writeShort(16*91);},"Oversized input duration rejected");
            synchronized(room){room.battle.pendingNext=true;for(GunnyServer.Session s:room.members)s.resolution=turn;room.tick();}ok(room.battle.turn==turn+1,"Turn barrier advances once when everyone has the result");int energy=room.battle.units[room.battle.active].energy;sync(a,turn,false,3,6,16*8+2);ok(room.battle.units[room.battle.active].energy==energy,"Late previous-turn frames cannot affect the next player");
            synchronized(room){for(int i=1;i<6;i+=2)room.battle.units[i].hp=0;room.battle.check();room.tick();}long end=System.currentTimeMillis()+4000;while(!room.settled&&System.currentTimeMillis()<end)Thread.sleep(20);ok(room.settled,"Six-player result settles with six distinct participants");int before=server.sessions.get(a).profile.coins;DataInputStream reward=call(a,"claim",o->o.writeByte(8));int card=reward.readUnsignedByte(),coins=reward.readUnsignedShort();ok(card==8&&coins>=500&&coins<=2000,"Server selects the card payout");call(a,"claim",o->o.writeByte(0));ok(server.sessions.get(a).profile.coins==before+coins,"Changing card on retry cannot grant another payout");reject(a,"claim",o->o.writeByte(9),"Card outside the 3x3 grid rejected");
            HttpResponse<String> index=HTTP.send(HttpRequest.newBuilder(URI.create(base+"/download/")).GET().build(),HttpResponse.BodyHandlers.ofString());ok(index.statusCode()==200&&index.body().contains("E72")&&!index.body().contains("<script")&&!index.body().contains("display:grid"),"Legacy download site works without JS or modern layout");
            for(String name:List.of("lobby","loading","room","battle"))for(String ext:List.of("jpg","png")){String image="review-"+name+"."+ext;HttpResponse<byte[]> pic=HTTP.send(HttpRequest.newBuilder(URI.create(base+"/download/"+image)).GET().build(),HttpResponse.BodyHandlers.ofByteArray());ok(pic.statusCode()==200&&pic.body().length>1000&&pic.headers().firstValue("Content-Type").orElse("").equals(ext.equals("png")?"image/png":"image/jpeg")&&index.body().contains(image),"E6 gallery serves "+image);}
            for(String device:List.of("E72-2009","E6")){String url=base+"/download/downloads/Gunny-"+device+"-Online-730.jar";HttpResponse<byte[]> part=HTTP.send(HttpRequest.newBuilder(URI.create(url)).header("Range","bytes=0-3").GET().build(),HttpResponse.BodyHandlers.ofByteArray());ok(part.statusCode()==206&&part.body().length==4&&part.body()[0]=='P'&&part.body()[1]=='K',"Download/resume serves valid "+device+" JAR");HttpResponse<String> head=HTTP.send(HttpRequest.newBuilder(URI.create(url)).method("HEAD",HttpRequest.BodyPublishers.noBody()).build(),HttpResponse.BodyHandlers.ofString());ok(head.statusCode()==200&&head.body().isEmpty()&&Long.parseLong(head.headers().firstValue("Content-Length").orElse("0"))>1000000,"HEAD reports installer size without sending it");}
            for(String path:List.of("/download/../.env","/download/%2e%2e/server/CloudStore.java","/download/downloads/local.env"))ok(HTTP.send(HttpRequest.newBuilder(URI.create(base+path)).GET().build(),HttpResponse.BodyHandlers.ofString()).statusCode()==404,"Static download cannot expose "+path);
            ok(HTTP.send(HttpRequest.newBuilder(URI.create(base+"/download/https.html")).GET().build(),HttpResponse.BodyHandlers.ofString()).body().contains("ssl.dll"),"PDF guide has readable phone HTML");
        }
        System.out.println("All 6.3.0 protocol and download checks passed");
    }
}
